// A blog post written in the admin (or generated by the AI pipeline), turned
// into the same markup a WordPress post carries.
//
// This is a port of `build_post.py` from the spenza-blog skill, which builds the
// markup of the live posts (TL;DR cards, themed scrollable tables, FAQ
// accordion, FAQPage schema, "Contact Us Today" button). Keeping one markup
// means a post written here and a post written in WordPress cannot drift apart,
// and the existing CSS bundles style both.
//
// Entry format (`src/content/cms-blog/<slug>.mdx`): YAML front matter plus a
// markdown body. The admin (Decap, `public/admin/config.yml`) writes it. Everything the layout
// needs beyond the prose is structured, so an editor never has to hand-write
// the cards or the FAQ markup.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml } from 'yaml';
import { unified } from 'unified';
import remarkParse from 'remark-parse';
import remarkGfm from 'remark-gfm';
import remarkRehype from 'remark-rehype';
import rehypeStringify from 'rehype-stringify';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ASSETS = path.join(HERE, 'cms-post');

// Authors, categories and tags are managed in the admin (Settings) and stored
// as JSON next to the posts, so adding one needs no code change.
export const META_DIR = process.env.CMS_META_DIR
  ? path.resolve(process.env.CMS_META_DIR)
  : path.join(HERE, '..', '..', 'src', 'content', 'cms-meta');
const readList = (file, key) => {
  try { return JSON.parse(fs.readFileSync(path.join(META_DIR, file), 'utf8'))[key] ?? []; } catch { return []; }
};
const byslug = list => Object.fromEntries(list.filter(x => x?.slug).map(x => [x.slug, x]));
export const AUTHORS = byslug(readList('authors.json', 'authors'));
export const CATEGORY_LIST = byslug(readList('categories.json', 'categories'));
export const CATEGORIES = Object.keys(CATEGORY_LIST);
export const TAG_LIST = byslug(readList('tags.json', 'tags'));
export const TLDR_HEADING = 'TL;DR / At-a-Glance Summary';
export const DEFAULT_ICONS = ['chart-line', 'coins', 'circle-check', 'clipboard-check', 'gears'];

const ATTRIBUTION =
  '<p>Prepared by <a href="https://spenza.com/about-us/">Spenza</a>, a connectivity management and ' +
  'telecom platform provider. <a href="https://spenza.com/contact-us/">Contact the Spenza team</a> ' +
  'for product-scope questions.</p>';

const BUTTON =
  '<div class="wp-block-uagb-buttons uagb-buttons__outer-wrap uagb-btn__default-btn ' +
  'uagb-btn-tablet__default-btn uagb-btn-mobile__default-btn uagb-block-68257511">' +
  '<div class="uagb-buttons__wrap uagb-buttons-layout-wrap">' +
  '<div class="wp-block-uagb-buttons-child uagb-buttons__outer-wrap uagb-block-74a16303 wp-block-button">' +
  '<div class="uagb-button__wrapper"><a class="uagb-buttons-repeater wp-block-button__link" ' +
  'href="https://spenza.com/contact-us/"><span class="uagb-button__link">Contact Us Today</span></a>' +
  '</div></div></div></div>';

const PLUS =
  '<svg aria-hidden="true" viewBox="0 0 448 512" xmlns="http://www.w3.org/2000/svg"><path d="M432 256c0 17.69-14.33 ' +
  '32.01-32 32.01H256v144c0 17.69-14.33 31.99-32 31.99s-32-14.3-32-31.99v-144H48c-17.67 0-32-14.32-32-32.01s14.33-31.99 ' +
  '32-31.99H192v-144c0-17.69 14.33-32.01 32-32.01s32 14.32 32 32.01v144h144C417.7 224 432 238.3 432 256z"></path></svg>';
const MINUS =
  '<svg aria-hidden="true" viewBox="0 0 448 512" xmlns="http://www.w3.org/2000/svg"><path d="M400 288h-352c-17.69 ' +
  '0-32-14.32-32-32.01s14.31-31.99 32-31.99h352c17.69 0 32 14.3 32 31.99S417.7 288 400 288z"></path></svg>';
const FAQ_OPEN =
  '<div class="wp-block-uagb-faq uagb-faq__outer-wrap uagb-block-5561fd5b uagb-faq-icon-row ' +
  'uagb-faq-layout-accordion uagb-faq-expand-first-true uagb-faq-inactive-other-true uagb-faq__wrap ' +
  'uagb-buttons-layout-wrap uagb-faq-equal-height" data-faqtoggle="true">';

const WRAPPER_HEAD = fs.readFileSync(path.join(ASSETS, 'wrapper-head.html'), 'utf8');
const WRAPPER_TAIL = fs.readFileSync(path.join(ASSETS, 'wrapper-tail.html'), 'utf8');

export const escapeHtml = s =>
  String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// ---- parsing ---------------------------------------------------------------

/** Split `---\nyaml\n---\nbody`. Throws a readable error for a malformed file. */
export function parseEntry(text, file = 'entry') {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(text);
  if (!m) throw new Error(`${file}: no front matter (expected a leading --- block)`);
  let meta;
  try {
    meta = parseYaml(m[1]) ?? {};
  } catch (err) {
    throw new Error(`${file}: front matter is not valid YAML (${err.message.split('\n')[0]})`);
  }
  if (typeof meta !== 'object' || Array.isArray(meta)) throw new Error(`${file}: front matter must be a map`);
  return { meta, body: m[2].replace(/^\s+/, '') };
}

const plain = s => String(s ?? '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/**
 * What an entry must satisfy before it is published.
 *
 * `errors` block publication (the loader skips the entry, the PR check goes
 * red); `warnings` are advice. The rules are the spenza-blog draft contract
 * where the layout depends on them, and deliberately looser where a human
 * writing by hand has a reason to differ: a TL;DR block and an FAQ are optional
 * on a manual post, but when present they must be complete.
 */
export function validateEntry(meta, body, { fileExists = () => true, filenameSlug } = {}) {
  const errors = [];
  const warnings = [];
  const need = (k, label = k) => {
    if (meta[k] === undefined || meta[k] === null || String(meta[k]).trim() === '') errors.push(`${label} is required`);
  };
  ['title', 'slug', 'description', 'category', 'author', 'publishedDate'].forEach(k => need(k));

  if (meta.slug && !SLUG_RE.test(String(meta.slug))) errors.push('slug must be lowercase letters, numbers and hyphens');
  if (meta.slug && String(meta.slug).length > 80) warnings.push('slug is longer than 80 characters');
  if (meta.slug && filenameSlug && meta.slug !== filenameSlug) errors.push(`slug "${meta.slug}" does not match the file name "${filenameSlug}"`);
  if (meta.category && !CATEGORIES.includes(meta.category)) errors.push(`category must be one of ${CATEGORIES.join(', ')}`);
  if (meta.author && !AUTHORS[meta.author]) errors.push(`author must be one of ${Object.keys(AUTHORS).join(', ')}`);
  for (const t of meta.tags ?? []) if (!TAG_LIST[t]) errors.push(`tag "${t}" is not in Settings > Tags; add it there first`);
  if (meta.publishedDate && Number.isNaN(new Date(meta.publishedDate).getTime())) errors.push('publishedDate is not a valid date');

  const d = String(meta.description ?? '');
  if (d && (d.length < 110 || d.length > 165)) {
    warnings.push(`description is ${d.length} characters; 110-165 shows fully in search results`);
  }

  const hero = meta.hero ?? {};
  if (!hero.image) errors.push('hero.image is required (it is the featured image and the social card)');
  else if (!fileExists(hero.image)) errors.push(`hero image not found: ${hero.image}`);
  if (hero.image && !String(hero.alt ?? '').trim()) errors.push('hero.alt is required: describe what the image shows');

  const bi = meta.bodyImage;
  if (bi?.image) {
    if (!fileExists(bi.image)) errors.push(`body image not found: ${bi.image}`);
    if (!String(bi.alt ?? '').trim()) errors.push('bodyImage.alt is required when a body image is set');
  }

  const cards = meta.tldr?.cards ?? [];
  if (cards.length || meta.tldr?.summary) {
    if (cards.length !== 5) errors.push(`TL;DR needs exactly 5 cards (4 key points + 1 "how Spenza helps"), found ${cards.length}`);
    if (!String(meta.tldr?.summary ?? '').trim()) errors.push('TL;DR needs a summary sentence');
    cards.forEach((c, i) => {
      if (!String(c?.title ?? '').trim() || !String(c?.text ?? '').trim()) errors.push(`TL;DR card ${i + 1} needs a title and text`);
    });
  } else {
    warnings.push('no TL;DR block: the summary and key-point cards are skipped on this post');
  }

  const faq = meta.faq ?? [];
  faq.forEach((f, i) => {
    if (!String(f?.question ?? '').trim() || !String(f?.answer ?? '').trim()) errors.push(`FAQ ${i + 1} needs a question and an answer`);
  });
  if (!faq.length) warnings.push('no FAQ: the post ships without the accordion and FAQPage schema');

  errors.push(...blockProblems(body, fileExists));
  if (/^\s*#\s/m.test(body)) errors.push('the body contains an H1; the title is the only H1');
  if (/in this guide|table of contents/i.test(body)) warnings.push('remove the "In this guide" / contents block (not used on Spenza posts)');
  if (!body.trim()) errors.push('the body is empty');
  return { errors, warnings };
}

/**
 * Rules for the Settings files (authors, categories, tags). A category slug
 * becomes the first segment of every post URL, so it must not collide with a
 * page the site already has.
 */
export function validateSettings({ authors = [], categories = [], tags = [] }, { reserved = [], fileExists = () => true } = {}) {
  const errors = [];
  const taken = new Set(reserved);
  const check = (kind, list, { label, needsLabel = 'name' } = {}) => {
    const seen = new Set();
    list.forEach((x, i) => {
      const at = `${kind} #${i + 1}${x?.slug ? ` (${x.slug})` : ''}`;
      if (!x?.slug || !SLUG_RE.test(x.slug)) errors.push(`${at}: the URL name must be lowercase letters, numbers and hyphens`);
      else if (seen.has(x.slug)) errors.push(`${at}: the URL name is used twice`);
      else seen.add(x.slug);
      if (!String(x?.[needsLabel] ?? '').trim()) errors.push(`${at}: needs a ${label ?? 'name'}`);
    });
  };
  check('Author', authors, { label: 'name' });
  check('Category', categories, { needsLabel: 'label', label: 'name' });
  check('Tag', tags, { needsLabel: 'label', label: 'name' });
  for (const c of categories) {
    if (c?.slug && taken.has(c.slug)) errors.push(`Category (${c.slug}): "${c.slug}" is already a page or section of the site; pick another URL name`);
  }
  for (const a of authors) {
    if (a?.avatar && !fileExists(a.avatar)) errors.push(`Author (${a.slug}): photo not found: ${a.avatar}`);
  }
  return errors;
}

// ---- body blocks (shortcodes) -------------------------------------------------
//
// The editor's "+" menu inserts a block as one line of text, so the body stays
// plain markdown and diffs cleanly in a pull request:
//   [[image src="/cms-media/x.webp" alt="..." caption="..."]]
//   [[embed url="https://www.youtube.com/watch?v=..." title="..."]]   (YouTube, Vimeo, Loom)
//   [[button text="Book a demo" url="https://spenza.com/contact-us/"]]
//   [[callout type="note|tip|warning" title="..." text="..."]]
// A quote inside a value is written \" and a line break is a space.

export const BLOCKS = ['image', 'embed', 'button', 'callout'];
const BLOCK_LINE = /^[ \t]*\[\[([a-z-]+)((?:\s+[a-zA-Z]+="(?:[^"\\]|\\.)*")*)\s*\]\][ \t]*$/;
const ATTR = /([a-zA-Z]+)="((?:[^"\\]|\\.)*)"/g;

function parseAttrs(src) {
  const out = {};
  for (const m of src.matchAll(ATTR)) out[m[1]] = m[2].replace(/\\"/g, '"');
  return out;
}

const EMBED_HOSTS = {
  youtube: u => {
    const h = u.hostname.replace(/^www\.|^m\./, '');
    let id = '';
    if (h === 'youtu.be') id = u.pathname.slice(1);
    else if (h === 'youtube.com' || h === 'youtube-nocookie.com') id = u.searchParams.get('v') || (/^\/(?:embed|shorts)\/([\w-]+)/.exec(u.pathname) ?? [])[1] || '';
    return /^[\w-]{6,20}$/.test(id) ? `https://www.youtube-nocookie.com/embed/${id}` : null;
  },
  vimeo: u => {
    const id = /^\/(\d{5,12})/.exec(u.pathname)?.[1];
    return u.hostname.replace(/^www\./, '') === 'vimeo.com' && id ? `https://player.vimeo.com/video/${id}` : null;
  },
  loom: u => {
    const id = /^\/(?:share|embed)\/([a-f0-9]{20,40})/.exec(u.pathname)?.[1];
    return u.hostname.replace(/^www\./, '') === 'loom.com' && id ? `https://www.loom.com/embed/${id}` : null;
  },
};

/** The player URL for a pasted video link, or null when the host is not allowed. */
export function embedSrc(url) {
  let u;
  try { u = new URL(String(url)); } catch { return null; }
  if (u.protocol !== 'https:') return null;
  for (const f of Object.values(EMBED_HOSTS)) {
    const r = f(u);
    if (r) return r;
  }
  return null;
}

const safeUrl = u => /^(https?:\/\/|\/|#|mailto:)/i.test(String(u ?? '').trim());

/** Every block line in a body, with its line number, for validation. */
export function findBlocks(body) {
  const out = [];
  String(body).split('\n').forEach((line, i) => {
    if (!/^\s*\[\[/.test(line)) return;
    const m = BLOCK_LINE.exec(line);
    out.push(m ? { line: i + 1, name: m[1], attrs: parseAttrs(m[2]) } : { line: i + 1, name: null, attrs: {} });
  });
  return out;
}

function blockProblems(body, fileExists) {
  const errors = [];
  for (const b of findBlocks(body)) {
    const at = `body line ${b.line}`;
    if (!b.name) { errors.push(`${at}: a [[block]] is malformed (values go in "double quotes")`); continue; }
    if (!BLOCKS.includes(b.name)) { errors.push(`${at}: unknown block [[${b.name}]] (use ${BLOCKS.join(', ')})`); continue; }
    const a = b.attrs;
    if (b.name === 'image') {
      if (!a.src) errors.push(`${at}: the image block has no image`);
      else if (!fileExists(a.src)) errors.push(`${at}: image not found: ${a.src}`);
      if (a.src && !String(a.alt ?? '').trim()) errors.push(`${at}: the image block needs alt text`);
    } else if (b.name === 'embed') {
      if (!embedSrc(a.url)) errors.push(`${at}: the embed link must be an https YouTube, Vimeo or Loom video link`);
    } else if (b.name === 'button') {
      if (!String(a.text ?? '').trim()) errors.push(`${at}: the button needs text`);
      if (!safeUrl(a.url)) errors.push(`${at}: the button link must start with https://, / or #`);
    } else if (b.name === 'callout') {
      if (!String(a.text ?? '').trim()) errors.push(`${at}: the callout needs text`);
    }
  }
  return errors;
}

const inlineButton = (text, url) => {
  const ext = /^https?:\/\//i.test(url) && !/^https?:\/\/(www\.)?spenza\.com/i.test(url);
  return BUTTON
    .replace('href="https://spenza.com/contact-us/"', `href="${escapeHtml(url)}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ''}`)
    .replace('Contact Us Today', escapeHtml(text));
};

/**
 * Block lines to HTML (each on one line so markdown treats it as a raw block).
 * Blank lines are added around the result so it is its own block.
 */
export async function expandBlocks(body, { imageDims } = {}) {
  const lines = String(body).split('\n');
  const out = [];
  for (const line of lines) {
    const m = BLOCK_LINE.exec(line);
    if (!m || !BLOCKS.includes(m[1])) { out.push(line); continue; }
    const a = parseAttrs(m[2]);
    let html = '';
    if (m[1] === 'image') {
      html = figureHtml({ image: a.src, alt: a.alt, caption: a.caption }, imageDims?.(a.src)).replace(/\n/g, '');
    } else if (m[1] === 'embed') {
      const src = embedSrc(a.url);
      html = `<div class="spenza-embed"><iframe src="${escapeHtml(src)}" title="${escapeHtml(a.title || 'Video')}" loading="lazy" ` +
        'allow="accelerometer; autoplay; clipboard-write; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>';
    } else if (m[1] === 'button') {
      html = `<div class="spenza-inline-button">${inlineButton(a.text, a.url)}</div>`;
    } else if (m[1] === 'callout') {
      const kind = ['note', 'tip', 'warning'].includes(a.type) ? a.type : 'note';
      html = `<aside class="spenza-callout spenza-callout-${kind}">` +
        (a.title ? `<strong>${escapeHtml(a.title)}</strong>` : '') + `<span>${await inlineMd(a.text)}</span></aside>`;
    }
    out.push('', html, '');
  }
  return out.join('\n');
}

const BLOCK_CSS = '<style>/* Body blocks inserted from the editor. */\n' +
  '.spenza-draft-content .spenza-embed{position:relative;width:100%;aspect-ratio:16/9;margin:28px 0;border-radius:12px;overflow:hidden;background:#111}\n' +
  '.spenza-draft-content .spenza-embed iframe{position:absolute;inset:0;width:100%;height:100%;border:0}\n' +
  '.spenza-draft-content .spenza-inline-button{margin:28px 0}\n' +
  '.spenza-draft-content .spenza-callout{display:block;margin:28px 0;padding:16px 20px;border-left:4px solid #ff4500;border-radius:8px;background:#fff4ee;line-height:1.6}\n' +
  '.spenza-draft-content .spenza-callout strong{display:block;margin-bottom:4px}\n' +
  '.spenza-draft-content .spenza-callout-tip{border-color:#0a7d3c;background:#e8f6ee}\n' +
  '.spenza-draft-content .spenza-callout-warning{border-color:#b3261e;background:#fdecea}\n' +
  '.spenza-draft-content figure img{max-width:100%;height:auto}</style>\n';


// ---- markdown -> themed HTML -----------------------------------------------

const isEl = (n, tag) => n && n.type === 'element' && (tag ? n.tagName === tag : true);
const textOf = n => (n.type === 'text' ? n.value : (n.children ?? []).map(textOf).join(''));
const el = (tagName, properties = {}, children = []) => ({ type: 'element', tagName, properties, children });

/**
 * The Spenza-specific shape of the body, as a rehype transform:
 * - numbered `section-N` ids on H2s
 * - tables get a caption (the heading above), `scope` on header cells, and the
 *   scroll wrappers the table CSS expects
 * - the body figure is placed at the marker, or after section N
 */
function rehypeSpenza({ figure, afterSection }) {
  return tree => {
    let h2 = 0;
    let lastHeading = 'Table';
    let placed = false;

    const wrapTable = table => {
      const cap = lastHeading;
      for (const n of walkAll(table)) if (isEl(n, 'th')) n.properties.scope = 'col';
      table.properties.className = ['responsive-table'];
      table.children.unshift(el('caption', { className: ['table-caption'] }, [{ type: 'text', value: cap }]));
      const scroll = el('div', { 'aria-label': cap, className: ['table-scroll'], role: 'region', tabIndex: 0 }, [table]);
      return el('div', { 'aria-label': 'Table', className: ['table-wrap'], role: 'region', tabIndex: 0 }, [scroll]);
    };

    const figureNode = figure ? { type: 'raw', value: figure } : null;
    // An explicit marker in the body decides the position; only without one does
    // "after section N" apply.
    const hasMarker = tree.children.some(n => n.type === 'raw' && /<!--\s*IMAGE:body\s*-->/.test(n.value));
    const out = [];
    for (const node of tree.children) {
      if (isEl(node, 'h2')) {
        h2 += 1;
        node.properties.id = `section-${h2}`;
        lastHeading = textOf(node).trim();
        if (figureNode && !placed && !hasMarker && afterSection && h2 === afterSection + 1) {
          out.push(figureNode);
          placed = true;
        }
      } else if (isEl(node, 'h3')) {
        lastHeading = textOf(node).trim();
      }
      if (node.type === 'raw' && /<!--\s*IMAGE:body\s*-->/.test(node.value)) {
        if (figureNode && !placed) { out.push(figureNode); placed = true; }
        const rest = node.value.replace(/<!--\s*IMAGE:body\s*-->/, '').trim();
        if (rest) out.push({ type: 'raw', value: rest });
        continue;
      }
      out.push(isEl(node, 'table') ? wrapTable(node) : node);
    }
    if (figureNode && !placed) out.push(figureNode);
    tree.children = out;
  };
}

function* walkAll(node) {
  yield node;
  for (const c of node.children ?? []) yield* walkAll(c);
}

const mdProcessor = extra =>
  unified()
    .use(remarkParse)
    .use(remarkGfm)
    .use(remarkRehype, { allowDangerousHtml: true })
    .use(extra ?? (() => () => {}))
    .use(rehypeStringify, { allowDangerousHtml: true });

/** One line of markdown (an FAQ answer) to inline HTML, without the wrapping <p>. */
export async function inlineMd(s) {
  const out = String(await mdProcessor().process(String(s ?? ''))).trim();
  return out.startsWith('<p>') && out.endsWith('</p>') ? out.slice(3, -4) : out;
}

function figureHtml(bodyImage, dims) {
  if (!bodyImage?.image) return '';
  const w = dims?.width ? ` width="${dims.width}"` : '';
  const h = dims?.height ? ` height="${dims.height}"` : '';
  const caption = String(bodyImage.caption ?? '').trim();
  return (
    `<figure>\n<img loading="lazy" decoding="async" alt="${escapeHtml(bodyImage.alt)}"${h} ` +
    `src="${escapeHtml(bodyImage.image)}"${w}/>\n` +
    (caption ? `<figcaption>${escapeHtml(caption)}</figcaption>\n` : '') +
    '</figure>'
  );
}

async function buildFaq(items) {
  if (!items.length) return '';
  const parts = ['<h2 class="wp-block-heading" id="faq"><strong>FAQs</strong></h2>', FAQ_OPEN];
  let i = 0;
  for (const f of items) {
    i += 1;
    parts.push(
      '<div class="wp-block-uagb-faq-child uagb-faq-child__outer-wrap uagb-faq-item" role="group" tabindex="0">' +
      `<div aria-controls="faq-answer-${i}" aria-expanded="false" class="uagb-faq-questions-button uagb-faq-questions" role="button"> ` +
      `<span class="uagb-icon uagb-faq-icon-wrap">\n${PLUS}\n</span>\n` +
      `<span class="uagb-icon-active uagb-faq-icon-wrap">\n${MINUS}\n</span>\n` +
      `<span class="uagb-question"><strong>${escapeHtml(f.question)}</strong></span></div>` +
      `<div class="uagb-faq-content" id="faq-answer-${i}"><p>${await inlineMd(f.answer)}</p></div></div>`
    );
  }
  parts.push('</div>');
  return parts.join('');
}

export const canonicalUrl = (siteUrl, meta) => `${siteUrl.replace(/\/$/, '')}/${meta.category}/${meta.slug}/`;

async function faqJsonLd(siteUrl, meta, items) {
  if (!items.length) return '';
  const data = {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    '@id': `${canonicalUrl(siteUrl, meta)}#faq`,
    mainEntity: await Promise.all(items.map(async f => ({
      '@type': 'Question',
      name: String(f.question),
      acceptedAnswer: { '@type': 'Answer', text: plain(await inlineMd(f.answer)) },
    }))),
  };
  return '\n<script type="application/ld+json">' + JSON.stringify(data).replace(/<\//g, '<\\/') + '</script>\n';
}

/**
 * The post body: styles, the `.spenza-draft-content` wrapper, the prose, the
 * FAQ accordion, the attribution and the Contact Us Today button.
 */
export async function renderContent(meta, body, { siteUrl, bodyImageDims, imageDims } = {}) {
  const afterSection = Number(meta.bodyImage?.afterSection ?? 2) || 0;
  const figure = figureHtml(meta.bodyImage, bodyImageDims);
  const html = String(await mdProcessor(() => rehypeSpenza({ figure, afterSection })).process(await expandBlocks(body, { imageDims })));
  const faq = (meta.faq ?? []).filter(f => f?.question && f?.answer);
  return (
    WRAPPER_HEAD + BLOCK_CSS +
    '<div class="spenza-draft-content">\n' +
    html + '\n' + (await buildFaq(faq)) + '\n<hr/>\n' + ATTRIBUTION + '\n' + BUTTON + '\n</div>\n' +
    WRAPPER_TAIL +
    (await faqJsonLd(siteUrl ?? 'https://spenza.com', meta, faq))
  );
}

/** `<i class="fa-classic fa-solid fa-NAME">`, the form WordPress stores for a card icon. */
const iconHtml = name => `<i class="fa-classic fa-solid fa-${name}" aria-hidden="true"></i>`;

export function templateBlocks(meta) {
  const cards = meta.tldr?.cards ?? [];
  if (cards.length !== 5) return { tldrHeading: '', tldrDescription: '', twoCol: [], oneCol: [] };
  const withIcon = (c, i) => ({ icon: iconHtml(c.icon || DEFAULT_ICONS[i]), title: String(c.title), text: String(c.text) });
  return {
    tldrHeading: TLDR_HEADING,
    tldrDescription: String(meta.tldr.summary),
    twoCol: cards.slice(0, 4).map(withIcon),
    oneCol: [withIcon(cards[4], 4)],
  };
}

// ---- the record the `posts` collection stores --------------------------------

const iso = d => new Date(d).toISOString().replace(/\.\d{3}Z$/, '+00:00');
const jsonLdEscape = s => s.replace(/\//g, '\\/');

/** The `<head>` Yoast gives a WordPress post, rebuilt from the entry's own fields. */
export function buildHead(meta, { siteUrl, content, hero, authorName }) {
  const url = canonicalUrl(siteUrl, meta);
  const title = escapeHtml(meta.seoTitle || meta.title);
  const desc = escapeHtml(meta.description);
  const published = iso(meta.publishedDate);
  const modified = iso(meta.updatedDate ?? meta.publishedDate);
  const image = hero?.url ? new URL(hero.url, siteUrl).href : '';
  const words = plain(content).split(' ').filter(Boolean).length;
  const minutes = Math.max(1, Math.round(words / 200));
  const graph = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Article', '@id': `${url}#article`, isPartOf: { '@id': url },
        author: { '@type': 'Organization', name: authorName, '@id': `${siteUrl}/#organization` },
        headline: meta.title, datePublished: published, dateModified: modified,
        mainEntityOfPage: { '@id': url }, wordCount: words, publisher: { '@id': `${siteUrl}/#organization` },
        ...(image ? { image: { '@id': `${url}#primaryimage` }, thumbnailUrl: image } : {}),
        keywords: (meta.tags ?? []).map(t => TAG_LIST[t]?.label ?? t), articleSection: [CATEGORY_LIST[meta.category]?.label ?? meta.category], inLanguage: 'en-US',
      },
      {
        '@type': 'WebPage', '@id': url, url, name: meta.seoTitle || meta.title, isPartOf: { '@id': `${siteUrl}/#website` },
        ...(image ? { primaryImageOfPage: { '@id': `${url}#primaryimage` }, image: { '@id': `${url}#primaryimage` }, thumbnailUrl: image } : {}),
        datePublished: published, dateModified: modified, description: meta.description,
        breadcrumb: { '@id': `${url}#breadcrumb` }, inLanguage: 'en-US',
        potentialAction: [{ '@type': 'ReadAction', target: [url] }],
      },
      ...(image ? [{ '@type': 'ImageObject', inLanguage: 'en-US', '@id': `${url}#primaryimage`, url: image, contentUrl: image, ...(hero.width ? { width: hero.width, height: hero.height } : {}), caption: meta.hero?.alt }] : []),
      {
        '@type': 'BreadcrumbList', '@id': `${url}#breadcrumb`,
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Home', item: `${siteUrl}/` },
          { '@type': 'ListItem', position: 2, name: CATEGORY_LIST[meta.category]?.label ?? meta.category, item: `${siteUrl}/category/${meta.category}/` },
          { '@type': 'ListItem', position: 3, name: meta.title },
        ],
      },
    ],
  };
  return [
    `<title>${title}</title>`,
    `<meta name="description" content="${desc}" />`,
    `<link rel="canonical" href="${url}" />`,
    '<meta property="og:locale" content="en_US" />',
    '<meta property="og:type" content="article" />',
    `<meta property="og:title" content="${title}" />`,
    `<meta property="og:description" content="${desc}" />`,
    `<meta property="og:url" content="${url}" />`,
    '<meta property="og:site_name" content="Spenza" />',
    `<meta property="article:published_time" content="${published}" />`,
    `<meta property="article:modified_time" content="${modified}" />`,
    ...(image
      ? [
        `<meta property="og:image" content="${escapeHtml(image)}" />`,
        ...(hero.width ? [`<meta property="og:image:width" content="${hero.width}" />`, `<meta property="og:image:height" content="${hero.height}" />`] : []),
      ]
      : []),
    `<meta name="author" content="${escapeHtml(authorName)}" />`,
    '<meta name="twitter:card" content="summary_large_image" />',
    '<meta name="twitter:label1" content="Written by" />',
    `<meta name="twitter:data1" content="${escapeHtml(authorName)}" />`,
    '<meta name="twitter:label2" content="Est. reading time" />',
    `<meta name="twitter:data2" content="${minutes} minutes" />`,
    `<script type="application/ld+json" class="yoast-schema-graph">${jsonLdEscape(JSON.stringify(graph))}</script>`,
  ].join('\n');
}

/** Stable positive id: WordPress ids are small, so 9xxxxxxx never collides with one. */
export const databaseIdFor = slug =>
  9_000_000 + (parseInt(createHash('sha1').update(String(slug)).digest('hex').slice(0, 6), 16) % 999_999);

/**
 * Entry file -> the record shape of the `posts` collection, or the problems that
 * stop it being one.
 */
export async function loadEntry(file, { siteUrl, publicDir, authorsMeta = {}, now = new Date() }) {
  const text = fs.readFileSync(file, 'utf8');
  const filenameSlug = path.basename(file).replace(/\.mdx?$/, '');
  const { meta, body } = parseEntry(text, path.basename(file));
  const onDisk = p => (p ? fs.existsSync(path.join(publicDir, p.replace(/^\//, ''))) : false);
  const { errors, warnings } = validateEntry(meta, body, { fileExists: onDisk, filenameSlug });
  if (errors.length) return { file, slug: meta.slug ?? filenameSlug, errors, warnings };

  const dims = async p => {
    try {
      const sharp = (await import('sharp')).default;
      const { width, height } = await sharp(path.join(publicDir, p.replace(/^\//, ''))).metadata();
      return { width, height };
    } catch { return {}; }
  };
  const heroDims = await dims(meta.hero.image);
  const bodyDims = meta.bodyImage?.image ? await dims(meta.bodyImage.image) : undefined;

  // A date in the future means "not yet": publishing by merging early would
  // otherwise leak the post, so the loader holds it until the day.
  const published = new Date(meta.publishedDate);
  if (published.getTime() > now.getTime()) return { file, slug: meta.slug, scheduled: published, errors: [], warnings };

  const inlineDims = {};
  for (const b of findBlocks(body)) if (b.name === 'image' && b.attrs.src) inlineDims[b.attrs.src] = await dims(b.attrs.src);
  const content = await renderContent(meta, body, { siteUrl, bodyImageDims: bodyDims, imageDims: p => inlineDims[p] });
  const a = AUTHORS[meta.author];
  const authorBase = authorsMeta[meta.author] ?? {};
  // A value set in Settings > Authors wins over the WordPress copy.
  const bio = a.bio || authorBase.bio;
  const avatar = a.avatar || authorBase.avatar;
  const author = { name: a.name, slug: meta.author, ...(bio ? { bio } : {}), ...(avatar ? { avatar } : {}) };
  const featuredImage = { url: meta.hero.image, alt: String(meta.hero.alt), ...heroDims };
  const modified = meta.updatedDate ? new Date(meta.updatedDate) : published;

  return {
    file,
    slug: meta.slug,
    warnings,
    errors: [],
    data: {
      databaseId: databaseIdFor(meta.slug),
      slug: String(meta.slug),
      title: String(meta.title),
      category: meta.category,
      categories: [meta.category],
      tags: (meta.tags ?? []).map(String),
      isCaseStudy: false,
      excerpt: `<p>${escapeHtml(meta.description)}</p>\n`,
      publishedDate: published,
      updatedDate: modified,
      author,
      featuredImage,
      seo: {
        title: String(meta.seoTitle || meta.title),
        description: String(meta.description),
        ogImage: new URL(meta.hero.image, siteUrl).href,
        fullHead: buildHead(meta, { siteUrl: siteUrl.replace(/\/$/, ''), content, hero: featuredImage, authorName: author.name }),
      },
      content,
      templateBlocks: templateBlocks(meta),
    },
  };
}

/** `*.mdx`/`*.md` entries in a directory, sorted for a stable build. */
export function listEntries(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter(f => /\.mdx?$/.test(f)).sort().map(f => path.join(dir, f));
}
